import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ALTUS PUBLICIDADE. Motion vertical de captação: agência de tráfego e social media para a área da saúde.
// Pouco material (só o logo) → motion: tipografia cinética, ícones e formas desenhadas na identidade do logo.
// Identidade: o "A" em fita verde (degradê #19E3A5 → #00A974) e o nome em branco, feitos para fundo escuro; letra Montserrat.
// Problema (agenda vazia) com visual genérico; a marca só entra na apresentação. Telas e cartões desenhados, ilustrativos.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos e na câmera de cada cena.
// V2 (pedido do dono: mais dinâmica): voz a 1,25x (src/voz-v2-125x.wav, 24,5 s), entradas com impulso, câmera com batidas nas
// palavras-chave, trocas com zoom e faixa verde. Os tempos continuam os da locução v1: t = (tempo do vídeo − LEAD) × SPD.
// V3: sem a pausa depois de "vazia" (voz-v3-125x-sem-pausa.wav: cortado 2,32–3,18 s da v1). Tempos da v1 depois do corte
// recebem + CUT: o trecho do corte nunca acontece.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const AL3_FPS = 30;
const LEAD = 0.2;
const SPD = 1.25;
const CUT_A = 2.32, CUT = 0.86;
export const AL3_FRAMES = Math.round(25.3 * AL3_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BG = "#04130E";
const BG2 = "#0B231B";
const LINE = "#1C3B30";
const WHITE = "#FFFFFF";
const MUTED = "#86AE9F";
const G = "#00C389";
const GL = "#19E3A5";
const GD = "#00A974";
const DEEP = "#03241A";
const GRAD = `linear-gradient(135deg, ${GL} 0%, ${GD} 100%)`;

// trocas de cena
const T2 = 5.85, T3 = 7.25, T4 = 9.95, T5 = 14.6, T6 = 19.55, T7 = 23.35, T8 = 27.15;

const blurIn = (t: number, at: number, out?: number, d = 0.36): React.CSSProperties => {
  const e = pop(t, at, d);
  const f = k(t, at, d * 0.7);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return {
    opacity: Math.min(1, f * 1.8) * (1 - o),
    filter: `blur(${((1 - f) * 12 + o * 14).toFixed(1)}px)`,
    transform: `translateY(${((1 - e) * 80 - o * 40).toFixed(1)}px) scale(${(0.78 + 0.22 * e + o * 0.08).toFixed(4)})`,
  };
};

// linhas de título: [texto, entrada, destaque?, tamanho?]; o destaque vem numa faixa de cor
type L = [string, number, boolean?, number?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlBg?: string; hlColor?: string; sub?: string }> = ({ t, items, size, top, color = WHITE, out, hlBg = GRAD, hlColor = DEEP, sub = MUTED }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.14 }}>
    {items.map(([w, at, hl, sz], i) => {
      const s = sz ?? size;
      return (
        <div key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: s, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? hlColor : sz && sz < size ? sub : color, ...(hl ? { background: hlBg, padding: `${s * 0.04}px ${s * 0.26}px ${s * 0.1}px`, borderRadius: s * 0.24 } : {}), ...blurIn(t, at, out) }}>
          {w}
        </div>
      );
    })}
  </div>
);

// câmera: só nos objetos, nunca no texto
const Cam: React.FC<{ t: number; a: number; b: number; ox?: number; oy?: number; z?: number; dx?: number; rot?: number; hits?: number[]; children: React.ReactNode }> = ({ t, a, b, ox = 540, oy = 1100, z = 0.08, dx = 0, rot = 0, hits = [], children }) => {
  const p = io(t, a, b);
  const hit = hits.reduce((m, h) => m + bump(t, h, 0.42), 0);
  const sh = hits.reduce((m, h) => m + bump(t, h, 0.3), 0);
  return <AbsoluteFill style={{ transformOrigin: `${ox}px ${oy}px`, transform: `translate(${(dx * 2 * (p - 0.5) + Math.sin(t * 57) * 9 * sh).toFixed(1)}px, ${(Math.cos(t * 49) * 7 * sh).toFixed(1)}px) scale(${(1 + z * p + 0.05 * hit).toFixed(4)}) rotate(${(rot * 2 * (p - 0.5)).toFixed(2)}deg)` }}>{children}</AbsoluteFill>;
};

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string; w?: number }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 1.8) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoTooth: Ico = ({ s, c, w }) => sv(s, c, <path d="M7 3c-2.5 0-4 2-4 4.5 0 2 1 3.5 1.5 5.5.5 2 .8 5.5 2.3 7.5.8 1 1.9.6 2.2-.6l.9-4c.2-.9.7-1.4 1.1-1.4s.9.5 1.1 1.4l.9 4c.3 1.2 1.4 1.6 2.2.6 1.5-2 1.8-5.5 2.3-7.5.5-2 1.5-3.5 1.5-5.5C21 5 19.5 3 17 3c-1.8 0-2.8 1-5 1S8.8 3 7 3z" />, w);
const IcoMind: Ico = ({ s, c, w }) => sv(s, c, <><path d="M15 21v-3a2 2 0 0 1 2-2h1.5l-.4-2.6L20 12l-2-4a7 7 0 0 0-13 2.5c0 2.3 1 4 2.5 5.3V21" /><path d="M11.5 9.6c-.8-.9-2.3-.6-2.5.6-.2 1 .7 1.8 2.5 3 1.8-1.2 2.7-2 2.5-3-.2-1.2-1.7-1.5-2.5-.6z" /></>, w);
const IcoBody: Ico = ({ s, c, w }) => sv(s, c, <><circle cx="12" cy="4.6" r="1.9" /><path d="M5 9.2l7 1.3 7-1.3M12 10.5v4.2l-3.2 6.3M12 14.7l3.2 6.3" /></>, w);
const IcoPlus: Ico = ({ s, c, w }) => sv(s, c, <path d="M12 5v14M5 12h14" />, w);
const IcoCheck: Ico = ({ s, c, w }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, w);
const IcoHeart: Ico = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 20.5s-7.5-4.6-9.2-9.3C1.7 8 3.6 4.5 7.1 4.5c2.1 0 3.6 1.2 4.9 3 1.3-1.8 2.8-3 4.9-3 3.5 0 5.4 3.5 4.3 6.7-1.7 4.7-9.2 9.3-9.2 9.3z" fill={c} /></svg>
);
const IcoMega: Ico = ({ s, c, w }) => sv(s, c, <><path d="M3.5 10v4a1 1 0 0 0 1 1H7l7 4.5V4.5L7 9H4.5a1 1 0 0 0-1 1z" /><path d="M7 15l1.5 5M18 9.5a3.5 3.5 0 0 1 0 5" /></>, w);
const IcoGrid: Ico = ({ s, c, w }) => sv(s, c, <><rect x="3.5" y="3.5" width="7" height="7" rx="1.6" /><rect x="13.5" y="3.5" width="7" height="7" rx="1.6" /><rect x="3.5" y="13.5" width="7" height="7" rx="1.6" /><rect x="13.5" y="13.5" width="7" height="7" rx="1.6" /></>, w);
const IcoChat: Ico = ({ s, c, w }) => sv(s, c, <path d="M4 18.5l1.3-3.6A7.5 7.5 0 1 1 8.6 18l-4.6.5z" />, w);
const IcoUp: Ico = ({ s, c, w }) => sv(s, c, <path d="M3.5 17l6-6 4 4 7-7.5M15 7.5h5.5V13" />, w);

// ───────── agenda da semana (genérica) ─────────
const DAYS = ["Seg", "Ter", "Qua", "Qui", "Sex"];
const ORDER = [6, 13, 1, 17, 9, 3, 15, 11, 0, 19, 7, 4, 16, 10, 2, 18, 12, 5, 14, 8];
const Agenda: React.FC<{ t: number; label: string; fill: number; full?: boolean }> = ({ t, label, fill, full }) => (
  <div style={{ width: 840, height: 820, borderRadius: 56, background: BG2, border: `3px solid ${LINE}`, boxSizing: "border-box", padding: "50px 46px", fontFamily: F, position: "relative" }}>
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
      <span style={{ fontWeight: 800, fontSize: 50, color: WHITE, letterSpacing: "-0.03em" }}>{label}</span>
      <span style={{ fontWeight: 700, fontSize: 30, color: full ? DEEP : MUTED, background: full ? G : "transparent", border: full ? "none" : `3px solid ${LINE}`, borderRadius: 40, padding: "8px 22px" }}>{full ? "agenda cheia" : "esta semana"}</span>
    </div>
    <div style={{ display: "flex", justifyContent: "space-between", marginTop: 42 }}>
      {DAYS.map((d) => (
        <div key={d} style={{ width: 134, textAlign: "center", fontWeight: 700, fontSize: 30, color: MUTED }}>{d}</div>
      ))}
    </div>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 134px)", justifyContent: "space-between", rowGap: 22, marginTop: 22 }}>
      {Array.from({ length: 20 }).map((_, i) => {
        const at = ORDER.indexOf(i);
        const on = fill > 0 ? pop(t, fill + at * 0.06, 0.35) : 0;
        return (
          <div key={i} style={{ height: 112, borderRadius: 22, position: "relative", border: `3px dashed #2F5A4A`, boxSizing: "border-box" }}>
            <div style={{ position: "absolute", inset: -3, borderRadius: 22, background: GRAD, padding: "22px 16px", boxSizing: "border-box", opacity: Math.min(1, on * 2), transform: `scale(${on.toFixed(3)})` }}>
              <div style={{ width: "80%", height: 14, borderRadius: 7, background: "rgba(3,36,26,0.55)" }} />
              <div style={{ width: "52%", height: 14, borderRadius: 7, background: "rgba(3,36,26,0.3)", marginTop: 14 }} />
            </div>
          </div>
        );
      })}
    </div>
  </div>
);

// ───────── cena 1 · gancho: a agenda vazia e a do concorrente lotando ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  if (t < 0.9) {
    const e = k(t, -0.25, 0.4);
    return (
      <AbsoluteFill style={{ background: BG, alignItems: "center", justifyContent: "center" }}>
        <div style={{ fontFamily: F, fontWeight: 800, fontSize: 132, color: WHITE, letterSpacing: "-0.045em", transform: `scale(${(2.1 - 1.1 * e + 0.12 * lin(t, 0, 0.9)).toFixed(4)})`, filter: `blur(${((1 - e) * 18).toFixed(1)}px)`, opacity: Math.min(1, e * 2) }}>Sua clínica</div>
      </AbsoluteFill>
    );
  }
  const SW = 3.3;   // "enquanto o concorrente": a agenda troca de dono (a pausa antes foi cortada)
  const flip = io(t, SW - 0.1, SW + 0.35);
  const up = k(t, 0.9, 0.6);
  const shake = t < SW ? Math.sin(t * 30) * 7 * bump(t, 1.5, 0.6) : 0;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Lines t={t} top={210} size={110} hlBg="#21362E" hlColor={WHITE} items={[["Sua clínica tem", 0.9, false, 56], ["agenda vazia", 1.0, true]]} out={2.12} />
      <Lines t={t} top={210} size={110} items={[["enquanto o concorrente", SW + 0.1, false, 56], ["lota a dele?", 4.3, true]]} />
      <Cam t={t} a={0.9} b={T2 + 0.4} oy={1180} z={0.1} rot={3} hits={[1.0, 4.3]}>
        <div style={{ position: "absolute", left: 120, top: 720, transformOrigin: "420px 410px", transform: `perspective(1800px) translate(${shake.toFixed(1)}px, ${((1 - up) * 900).toFixed(1)}px) rotateY(${(flip < 0.5 ? flip * 180 : (flip - 1) * 180).toFixed(1)}deg) scale(${(1 + 0.04 * bump(t, 4.3, 0.4)).toFixed(4)})` }}>
          {flip < 0.5 ? <Agenda t={t} label="Sua agenda" fill={0} /> : <Agenda t={t} label="Concorrente" fill={3.7} full={t > 4.9} />}
        </div>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · a marca: o "A" em fita entra girando, o nome logo abaixo ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const e = pop(t, T2 + 0.05, 0.6);
  const ring = lin(t, T2 + 0.1, T2 + 1.1);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Cam t={t} a={T2} b={T3 + 0.4} oy={900} z={0.14} rot={-4} hits={[5.95, 6.35]}>
        <div style={{ position: "absolute", left: 540, top: 820, width: 0, height: 0 }}>
          <div style={{ position: "absolute", width: 900, height: 900, left: -450, top: -450, borderRadius: 900, background: "radial-gradient(circle, rgba(0,195,137,0.22) 0%, rgba(0,195,137,0) 62%)", opacity: e }} />
          <div style={{ position: "absolute", width: 300 + ring * 1300, height: 300 + ring * 1300, borderRadius: 3000, border: `${(8 * (1 - ring)).toFixed(1)}px solid ${G}`, transform: "translate(-50%, -50%)", opacity: 0.6 * (1 - ring) }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 560, display: "flex", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${(0.3 + 0.7 * e).toFixed(4)}) rotate(${((1 - e) * -60).toFixed(1)}deg)` }}>
          <Img src={staticFile("altus/simbolo.png")} style={{ width: 600 }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1140, display: "flex", justifyContent: "center", ...blurIn(t, 6.3, undefined, 0.45) }}>
          <Img src={staticFile("altus/nome.png")} style={{ width: 760 }} />
        </div>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · agência de tráfego focada na saúde: o batimento vira seta de crescimento ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const draw = k(t, 7.5, 2.0);
  const head = pop(t, 9.2, 0.45);
  const path = "M40 260 L250 260 L300 200 L350 320 L420 60 L490 380 L540 220 L600 260 L700 260 L800 150 L900 40";
  return (
    <AbsoluteFill style={{ background: G }}>
      <Lines t={t} top={250} size={124} color={DEEP} hlBg={DEEP} hlColor={WHITE} items={[["Agência", 7.39], ["de tráfego", 7.75]]} />
      <Lines t={t} top={640} size={96} color={DEEP} sub="rgba(3,36,26,0.7)" hlBg={DEEP} hlColor={GL} items={[["focada na", 8.31, false, 62], ["área da saúde", 9.0, true]]} />
      <Cam t={t} a={T3} b={T4 + 0.4} ox={540} oy={1400} z={0.16} dx={-120} hits={[8.3, 9.0]}>
        <svg width={940} height={420} viewBox="0 0 940 420" style={{ position: "absolute", left: 70, top: 1130, overflow: "visible" }}>
          <path d={path} fill="none" stroke="rgba(3,36,26,0.18)" strokeWidth={22} strokeLinecap="round" strokeLinejoin="round" />
          <path d={path} fill="none" stroke={DEEP} strokeWidth={22} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={`${draw.toFixed(4)} 1`} />
          <g transform={`translate(900 40) rotate(42) scale(${head.toFixed(3)})`}>
            <path d="M-46 34 L0 -20 L46 34" fill="none" stroke={DEEP} strokeWidth={22} strokeLinecap="round" strokeLinejoin="round" />
          </g>
          <circle cx={420} cy={60} r={18 + 10 * bump(t, 8.3, 0.5)} fill={WHITE} opacity={draw > 0.45 ? 1 : 0} />
        </svg>
      </Cam>
    </AbsoluteFill>
  );
};

// ───────── cena 4 · as áreas: uma por batida no mesmo lugar, depois todas juntas ─────────
const AREAS: { at: number; out: number; name: string; I: Ico }[] = [
  { at: 10.2, out: 11.05, name: "Odontologia", I: IcoTooth },
  { at: 11.2, out: 12.1, name: "Psicologia", I: IcoMind },
  { at: 12.26, out: 13.45, name: "Fisioterapia", I: IcoBody },
];
const S4: React.FC<{ t: number }> = ({ t }) => {
  const MORE = 13.58;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Lines t={t} top={300} size={52} color={MUTED} items={[["Para toda a área da saúde", T4 + 0.1]]} />
      <Cam t={t} a={T4} b={T5 + 0.4} oy={880} z={0.12} rot={3} hits={[10.2, 11.2, 12.26, 13.58]}>
        {AREAS.map(({ at, out, I }, i) => {
          const e = pop(t, at - 0.05, 0.5);
          const o = lin(t, out, out + 0.18);
          const life = lin(t, at, out);
          return (
            <div key={i} style={{ position: "absolute", left: 540, top: 880, width: 0, height: 0, opacity: Math.min(1, e * 2) * (1 - o) }}>
              <svg width={560} height={560} viewBox="-280 -280 560 560" style={{ position: "absolute", left: -280, top: -280, transform: `rotate(${(-90 + life * 70).toFixed(1)}deg)` }}>
                <circle r={250} fill="none" stroke={LINE} strokeWidth={12} />
                <circle r={250} fill="none" stroke={G} strokeWidth={12} strokeLinecap="round" strokeDasharray={`${(1571 * k(t, at, 0.9)).toFixed(0)} 1571`} />
              </svg>
              <div style={{ position: "absolute", left: -200, top: -200, width: 400, height: 400, borderRadius: 400, background: GRAD, display: "flex", alignItems: "center", justifyContent: "center", transform: `translateY(${(Math.sin(t * 3 + i) * 12).toFixed(1)}px) scale(${e.toFixed(4)}) rotate(${((1 - e) * -35 + Math.sin(t * 2.6 + i) * 6).toFixed(2)}deg)` }}>
                <I s={230} c={DEEP} w={1.7} />
              </div>
            </div>
          );
        })}
        {/* e muito mais: as três áreas e o "+" lado a lado */}
        {[IcoTooth, IcoMind, IcoBody, IcoPlus].map((I, i) => {
          const e = pop(t, MORE - 0.05 + i * 0.09, 0.45);
          const x = 540 - 3 * 105 + i * 210;
          return (
            <div key={i} style={{ position: "absolute", left: x - 90, top: 880 - 90 + Math.sin(t * 3 + i * 1.3) * 10, width: 180, height: 180, borderRadius: 180, background: i === 3 ? WHITE : GRAD, display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${e.toFixed(4)})` }}>
              <I s={104} c={DEEP} w={i === 3 ? 2.6 : 1.8} />
            </div>
          );
        })}
      </Cam>
      {AREAS.map(({ at, out, name }, i) => (
        <Lines key={i} t={t} top={1260} size={108} items={[[name, at]]} out={out} />
      ))}
      <Lines t={t} top={1260} size={100} items={[["e muito mais", MORE, true]]} />
    </AbsoluteFill>
  );
};

// ───────── cena 5 · o número: mais de R$ 1,3 milhão faturados para os clientes ─────────
const S5: React.FC<{ t: number }> = ({ t }) => {
  const c = io(t, 15.55, 16.6);
  const v = (Math.round(13 * c) / 10).toFixed(1).replace(".", ",");
  const land = bump(t, 16.6, 0.45);
  const BARS = [0.22, 0.3, 0.27, 0.42, 0.5, 0.47, 0.66, 0.78, 1];
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Lines t={t} top={300} size={66} color={MUTED} items={[["Já são mais de", 14.94]]} />
      <Cam t={t} a={T5} b={T6 + 0.4} oy={1640} z={0.12} dx={80} hits={[16.6, 18.44]}>
        <div style={{ position: "absolute", left: 540 - 520, top: 640 - 300, width: 1040, height: 760, borderRadius: 1000, background: "radial-gradient(ellipse, rgba(0,195,137,0.2) 0%, rgba(0,195,137,0) 65%)", opacity: k(t, 15.5, 1) }} />
        {/* faíscas quando o número assenta */}
        {Array.from({ length: 16 }).map((_, i) => {
          const p = k(t, 16.6, 0.9);
          const ang = (i / 16) * Math.PI * 2 + 0.2;
          const r = 120 + p * (330 + (i % 3) * 70);
          return p > 0 && p < 1 ? <div key={i} style={{ position: "absolute", left: 640 + Math.cos(ang) * r * 1.3 - 9, top: 560 + Math.sin(ang) * r - 9, width: 18, height: 18, borderRadius: 18, background: i % 2 ? GL : WHITE, opacity: 1 - p, transform: `scale(${(1 - p * 0.6).toFixed(3)})` }} /> : null;
        })}
        {/* gráfico subindo junto com o número */}
        <div style={{ position: "absolute", left: 160, right: 160, top: 1440, height: 300, display: "flex", alignItems: "flex-end", justifyContent: "space-between" }}>
          {BARS.map((h, i) => (
            <div key={i} style={{ width: 58, height: 300 * h * k(t, 15.4 + i * 0.12, 0.7) * (1 + 0.03 * Math.sin(t * 2.4 + i)), borderRadius: 16, background: i === BARS.length - 1 ? GRAD : LINE }} />
          ))}
        </div>
      </Cam>
      <div style={{ position: "absolute", left: 0, right: 0, top: 420, display: "flex", justifyContent: "center", alignItems: "baseline", fontFamily: F, fontWeight: 800, letterSpacing: "-0.05em", ...blurIn(t, 15.5, undefined, 0.35) }}>
