export const AltusV3: React.FC = () => {
  const tn = (useCurrentFrame() / AL3_FPS - LEAD) * SPD;
  const t = tn < CUT_A ? tn : tn + CUT;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        const q = i + 1 < SCENES.length ? interpolate(t, [SCENES[i + 1][0], SCENES[i + 1][0] + 0.42], [0, 1], { ...cl, easing: INOUT }) : 0;
        return (
          <AbsoluteFill key={i} style={{ ...(p < 1 ? { clipPath: clip(p) } : {}), transform: `scale(${((1.18 - 0.18 * p) * (1 + 0.1 * q)).toFixed(4)})`, filter: q > 0 ? `blur(${(q * 10).toFixed(1)}px)` : undefined }}>
            <S t={t} />
          </AbsoluteFill>
        );
      })}
      {SCENES.slice(1).map(([at], i) => {
        const p = lin(t, at - 0.12, at + 0.4);
        if (p <= 0 || p >= 1) return null;
        const dir = i % 2 ? -1 : 1;
        return <div key={i} style={{ position: "absolute", left: -600, top: -400, width: 520, height: 2800, background: GRAD, transform: `translateX(${(dir > 0 ? -400 + p * 2600 : 2200 - p * 2600).toFixed(1)}px) rotate(${dir * 18}deg)`, opacity: 0.95 }} />;
      })}
    </AbsoluteFill>
  );
};

